import { defineConfig } from '@playwright/test';

/*
 * Playwright config
 * Generated by @jterrats/setup-agents — sf setup-agents local --profile qa
 *
 * Runnable after installing Playwright once:
 *   npm install --save-dev @playwright/test && npx playwright install
 *
 * Then author specs under test/e2e/ and run:
 *   SF_TARGET_ORG=<alias> npx playwright test
 *
 * Auth reuses the active SF CLI session via src/utils/salesforce-auth.ts — no
 * credentials in specs. In CI (no SF CLI), inject SALESFORCE_INSTANCE_URL +
 * SALESFORCE_ACCESS_TOKEN instead (see test/utils and the QA run-playwright playbook).
 */
